/**
 * Lightweight dot/bracket path extraction for `--select`, shared by any command that emits
 * a JSON success envelope (query, cicd operations). Supports the common subset needed for
 * scripting: `records[0].sys_id`, `result.links.progress.id`, `foo.bar[2].baz`.
 *
 * This intentionally is not a JMESPath/jq implementation — just enough to pull one value out
 * of a known JSON shape without requiring an external dependency (pipe to `jq` for anything
 * more advanced: filters, wildcards, projections).
 */
const PATH_TOKEN_REGEX = /[^.[\]]+|\[\d+\]/g

export function resolveJsonPath(value: unknown, path: string): unknown {
    const tokens = path.match(PATH_TOKEN_REGEX) ?? []
    let current: unknown = value

    for (const token of tokens) {
        if (current === undefined || current === null) {
            return undefined
        }
        if (token.startsWith('[')) {
            if (!Array.isArray(current)) {
                return undefined
            }
            current = current[Number(token.slice(1, -1))]
        } else {
            if (typeof current !== 'object') {
                return undefined
            }
            current = (current as Record<string, unknown>)[token]
        }
    }

    return current
}

/**
 * Formats a value resolved by `resolveJsonPath` for stdout.
 * `raw`: strings print unquoted (for direct shell interpolation via `$()`), everything
 * else falls back to compact JSON. `!raw`: always compact JSON (so `undefined` prints as `null`).
 */
export function formatSelectedValue(value: unknown, raw: boolean): string {
    if (raw) {
        if (value === undefined) {
            return ''
        }
        return typeof value === 'string' ? value : JSON.stringify(value)
    }
    return JSON.stringify(value ?? null)
}

/**
 * Prints a machine-mode envelope (query/cicd/api's `{ok: true, ...}` / `{ok: false, ...}` shapes),
 * applying --select/--output raw if requested. Used for both success and error envelopes so
 * --select works against a failure the same way it does against a result.
 */
export function printMachineEnvelope(envelope: unknown, args: { select?: string; output?: 'json' | 'raw' }): void {
    if (args.select !== undefined) {
        console.log(formatSelectedValue(resolveJsonPath(envelope, args.select), args.output === 'raw'))
    } else {
        console.log(JSON.stringify(envelope))
    }
}
